test('RPD additional compiled-Android cases cover limited and unrestricted accumulation', () => {
  for (const [inputs, expected] of rpdAndroidCases) {
    const r = math.rpd(...inputs);
    assert.ok(r, JSON.stringify(inputs));
    const actual = [r.volume, r.accumulation, r.deltaLevel, r.rho, r.deltaP, r.off, r.start, r.actualRun];
    actual.forEach((value, index) => assert.ok(
      Math.abs(value - expected[index]) < 1e-10,
      JSON.stringify(inputs) + ': output ' + index + ' = ' + value + ', Android = ' + expected[index],
    ));
    assert.ok(r.accumulation <= inputs[9] + 1e-9, 'Accumulation must respect the input limit');
    assert.ok(r.actualRun <= inputs[8] + 1e-9, 'The calculation must not lengthen the input runtime');
  }
});
